      return `Tampilkan ${p.filter}`;
    default: {
      const tidakMungkin: never = p;
      return tidakMungkin;
    }
  }
}
console.log(jelaskan({ jenis: "tambah", judul: "Belajar union" }));
console.log(jelaskan({ jenis: "hapus", id: 3 }));
console.log(jelaskan({ jenis: "daftar", filter: "aktif" }));

