type Aksi = { jenis: "naik"; n: number } | { jenis: "reset" };
function terapkan(nilai: number, a: Aksi): number {
  switch (a.jenis) {
    case "naik":
      return nilai + a.n;
    case "reset":
      return 0;
  }
}
let x = 0;
const aksi: Aksi[] = [{ jenis: "naik", n: 5 }, { jenis: "naik", n: 2 }, { jenis: "reset" }, { jenis: "naik", n: 1 }];
for (const a of aksi) x = terapkan(x, a);
console.log(x);

