type Aksi = { jenis: "tambah"; n: number } | { jenis: "kurang"; n: number } | { jenis: "reset" };
function reducer(nilai: number, a: Aksi): number {
  switch (a.jenis) {
    case "tambah":
      return nilai + a.n;
    case "kurang":
      return nilai - a.n;
    case "reset":
      return 0;
    default: {
      const tidakMungkin: never = a;
      return tidakMungkin;
    }
  }
}
let nilai = 0;
const semua: Aksi[] = [{ jenis: "tambah", n: 10 }, { jenis: "kurang", n: 3 }, { jenis: "reset" }, { jenis: "tambah", n: 4 }];
for (const a of semua) {
  nilai = reducer(nilai, a);
  console.log(nilai);
}
